var app = new Vue({
  el: "#app",
  delimiters: ["[[", "]]"],
  data: {
    errors: [],
    newBookText: null,
    ans: [],
  },
  methods: {
    getData() {
      const path =
        window.location.origin + "/dashboard/wordbooks/data";
      axios
        .get(path)
        .then((response) => {
          this.ans = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    addNewBook() {
      if (!this.newBookText) {
        this.errors.push("Không được để trống!");
      } else {
        this.ans.push({
          name: this.newBookText,
          content: [
            {
              stype: "text",
              scontent: "",
            },
          ],
        });
        this.errors = [];
        this.newBookText = null;
        this.updatePasive();
      }
    },
    deleteBook(key) {
      this.ans.splice(key, 1);
      this.updatePasive();
    },
    addNewQues(key) {
      this.ans[key].content.push({
        stype: "text",
        scontent: "",
      });
      this.updatePasive();
    },
    deleteQues(key, index) {
      this.ans[key].content.splice(index, 1);
      this.updatePasive();
    },
    updateData() {
      const path = window.location.origin + "/dashboard/wordbooks";
      axios
        .post(path, {
          data: this.ans,
        })
        .then((response) => {
          this.$notify({
            group: 'notification',
            type: response.data["status"],
            title: response.data["title"],
            text: response.data["message"],
            duration: 2500,
            speed: 1000
          })
        })
        .catch((error) => {
          console.log(error);
        });
    },
    updatePasive() {
      const path = window.location.origin + "/dashboard/wordbooks";
      axios
        .post(path, {
          data: this.ans,
        })
        .catch((error) => {
          console.log(error);
        });
    },
  },
  computed: {
    dragOptions() {
      return {
        animation: 0,
        group: "description",
        disabled: false,
        ghostClass: "ghost",
      };
    },
  },
  created() {
    this.getData();
  },
});
